import{_ as a,o as e,c as i,a3 as t}from"./chunks/framework.Ch_0qWu9.js";const k=JSON.parse('{"title":"Offline Solver 适配器","description":"","frontmatter":{"sourcePath":"docs/offline-adapters.zh-CN.md","sourceUrl":"https://github.com/MoonshotAI/TCSExam/blob/aab56977addd5d217972b7f35cf50be4440cb6c7/docs/offline-adapters.zh-CN.md","alternateUrl":"/TCSExam/docs/offline-adapters/","alternateAnchors":{"offline-solver-适配器":"offline-solver-adapters","运行套件":"run-a-suite","执行主机资源":"execution-host-resources","判分与结果":"judging-and-results","故障排查":"troubleshooting","构建选定适配器":"build-a-selected-adapter","offline-solver-adapters":"offline-solver-adapters","run-a-suite":"run-a-suite","execution-host-resources":"execution-host-resources","judging-and-results":"judging-and-results","troubleshooting":"troubleshooting","build-a-selected-adapter":"build-a-selected-adapter"}},"headers":[],"relativePath":"zh/offline-adapters/index.md","filePath":"zh/offline-adapters/index.md"}'),o={name:"zh/offline-adapters/index.md"};function r(l,s,n,d,h,p){return e(),i("div",null,[...s[0]||(s[0]=[t(`<p><a id="offline-solver-adapters"></a></p><h1 id="offline-solver-适配器" tabindex="-1">Offline Solver 适配器 <a class="header-anchor" href="#offline-solver-适配器" aria-label="Permalink to &quot;Offline Solver 适配器&quot;">​</a></h1><p>本指南描述 Offline Solver 判分的本地 Docker 执行方式。 面向准备公开自测与隐藏终判的用户。</p><p><a id="run-a-suite"></a></p><h2 id="运行套件" tabindex="-1">运行套件 <a class="header-anchor" href="#运行套件" aria-label="Permalink to &quot;运行套件&quot;">​</a></h2><p><a href="/TCSExam/docs/zh/getting-started/">安装运行时并配置模型</a>后，运行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tcsexam</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --suite</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lite</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --track</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> solver</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --solver-protocol</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> offline</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tcsexam</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --suite</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lite</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --track</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> solver</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --solver-protocol</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> offline</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tcsexam</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --suite</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lite</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --track</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> solver</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --solver-protocol</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> offline</span></span></code></pre></div><p>使用 <code>--suite full</code> 运行全部三十道 Solver 题，或用 <code>--task TASK_ID</code> 选择一道题。 构建器准备开发镜像和验证器镜像，并将其身份信息保存到本地缓存。 <code>doctor</code> 检查选定镜像和执行主机。开始运行前，先解决其报告的阻塞问题。</p><p>终判期间，Harbor 启动一个验证器控制器。控制器创建隔离的 Docker 工作容器， 提供提交内容和分配的隐藏输入，收集结果并删除其工作容器。 Offline 执行使用每次尝试独立的控制器；Online 服务部署见 <a href="/TCSExam/docs/zh/backend/docker/">Docker 后端指南</a>。</p><p><a id="execution-host-resources"></a></p><h2 id="执行主机资源" tabindex="-1">执行主机资源 <a class="header-anchor" href="#执行主机资源" aria-label="Permalink to &quot;执行主机资源&quot;">​</a></h2><p>执行主机需使用以 root 权限运行的 Linux Docker 守护进程，并提供 <code>/var/run/docker.sock</code>。 验证器的 <code>tests/docker-compose.yaml</code> 挂载此套接字及只读主机 cgroup 树， 使用主机 PID 和 cgroup 命名空间。CLI 用户需要 Docker 访问权限。 此 compose 配置要求标准套接字路径，即使选择了 Docker context 也一样。</p><p>套接字仅供可信验证器控制器使用。开发容器和判分工作容器运行时均不持有该套接字。 判分工作容器还需要 <a href="/TCSExam/docs/zh/judge-execution-isolation/">Landlock 和镜像预检</a>； 构建和求解器命令在 root 监督下以 UID/GID 65534 运行。</p><p>各题的 <code>tests/runtime/task.json</code> 声明工作容器资源预留。 只有 CPU 和内存预留资源足够时，控制器才允许启动工作容器，另外为控制器预留一个 CPU 和 512 MiB。 例如，32 GiB 的工作容器需要至少 33,280 MiB 可见主机内存，准入时还需有足够的空闲内存和磁盘。 四 CPU 工作容器需要至少五个可见 CPU，包含控制器预留。 开发容器另有资源要求，会在模型执行前检查。</p><p>每道题最多同时使用十个判分工作容器。较小主机同时运行较少的工作容器， 但保留各工作容器的资源和各实例的求解器预算。题目声明分片共享内存时，工作容器预留完整额度。 容量不足会产生环境错误，并在报告中列出所需资源。</p><p><a id="judging-and-results"></a></p><h2 id="判分与结果" tabindex="-1">判分与结果 <a class="header-anchor" href="#判分与结果" aria-label="Permalink to &quot;判分与结果&quot;">​</a></h2><p>各工作容器为分配到的实例调用题目的准备脚本和检查器。 检查器验证候选输出并计算其目标值。控制器将完整实例记录合并成最终题目结果。 题目奖励、判分失败和 Index 计算见<a href="/TCSExam/docs/zh/scoring/">计分</a>。</p><p>装箱、图划分、体育赛程安排、逻辑综合、二次指派和集合覆盖均只使用一个工作容器， 覆盖完整的共享时间池：所有实例共用一个求解器总预算。配置并行度时须保持这些组完整。 其他题目使用声明的逐实例限额和分组。</p><p>工作容器的外层截止时间为编译、求解和验证留出时间。 计分程序单独执行题目的求解器预算限制。计分器使用的 CPU 编号映射到为其工作容器预留的 CPU。</p><p><a id="troubleshooting"></a></p><h2 id="故障排查" tabindex="-1">故障排查 <a class="header-anchor" href="#故障排查" aria-label="Permalink to &quot;故障排查&quot;">​</a></h2><p>读法说明：根据现象查看相应处理方法。</p><table tabindex="0"><thead><tr><th>现象</th><th>处理方法</th></tr></thead><tbody><tr><td>Docker 套接字或 cgroup 访问失败</td><td>在以 root 权限运行 Docker 的主机上执行，使用标准套接字和题目的验证器 compose 配置。</td></tr><tr><td>判分启动报告隔离错误</td><td>在该主机上运行镜像预检，解决所报告的内核、系统调用或身份切换要求。</td></tr><tr><td>工作容器准入报告容量不足</td><td>释放所需资源或选择更大的主机；保留题目声明的工作容器规格。</td></tr><tr><td>初始归档上传失败</td><td>检查 <code>resources.json</code>。对于特定的启动前根目录缺失错误，控制器会用相同提交和实例组自动重试，最多三次。其他错误会报告给运维人员处理。</td></tr><tr><td>缺少结果或判分失败</td><td>计算题目分数前，检查验证器日志和实例记录。</td></tr></tbody></table><p><a id="build-a-selected-adapter"></a></p><h2 id="构建选定适配器" tabindex="-1">构建选定适配器 <a class="header-anchor" href="#构建选定适配器" aria-label="Permalink to &quot;构建选定适配器&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tcsexam</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --suite</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> full</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --task</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ce-pace2021</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --solver-protocol</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> offline</span></span></code></pre></div><p>题目的 <code>offline-adapter.json</code> 声明 Online 开发镜像、后端和验证工具依赖。 构建器解析这些依赖，并复用未变化的本地产物。资源输入和缓存选项见 <a href="/TCSExam/docs/zh/resources/">资源准备</a>。开发和源码检查见<a href="/TCSExam/docs/zh/contributing/">贡献指南</a>。</p>`,28)])])}const u=a(o,[["render",r]]);export{k as __pageData,u as default};
